// Even though Bridgehub is defined in `zksync_os_contract_interface`, we redefine it here,
// since for an upgrade we need much more internals than the rest of the codebase cares about.
alloy::sol! {
    #![sol(all_derives)]

    #[sol(rpc)]
    contract Bridgehub {
        address public chainAssetHandler;

        // Getters
        function owner() external view returns (address);
        function chainTypeManager(uint256 _chainId) external view returns (address);
        function getZKChain(uint256 _chainId) external view returns (address);

        // Upgrade functionality, only available for v30
        function pauseMigration() external;
    }

    #[sol(rpc)]
    contract ChainAssetHandlerBase {
        // available for >= v31
        function pauseMigration() external;
        function owner() external view returns (address);
    }

    enum Action {
        Add,
        Replace,
        Remove
    }

    struct Facet {
        address addr;
        bytes4[] selectors;
    }

    struct FacetCut {
        address facet;
        Action action;
        bool isFreezable;
        bytes4[] selectors;
    }

    struct DiamondCutData {
        FacetCut[] facetCuts;
        address initAddress;
        bytes initCalldata;
    }

    struct Call {
        address target;
        uint256 value;
        bytes data;
    }

    #[sol(rpc)]
    contract ChainTypeManagerV30 {
        function owner() external view returns (address);

        function setNewVersionUpgrade(
            DiamondCutData calldata _cutData,
            uint256 _oldProtocolVersion,
            uint256 _oldProtocolVersionDeadline,
            uint256 _newProtocolVersion
        ) external;

        function getProtocolVersion(uint256 _chainId) external view returns (uint256);
    }

    #[sol(rpc)]
    contract ChainTypeManager {
        function owner() external view returns (address);

        function setNewVersionUpgrade(
            DiamondCutData calldata _cutData,
            uint256 _oldProtocolVersion,
            uint256 _oldProtocolVersionDeadline,
            uint256 _newProtocolVersion,
            address _verifier
        ) external;

        function setUpgradeDiamondCut(
            DiamondCutData calldata _cutData,
            uint256 _oldProtocolVersion
        ) external;

        function getProtocolVersion(uint256 _chainId) external view returns (uint256);

        function L1_BYTECODES_SUPPLIER() external view returns (address);

        function serverNotifierAddress() external view returns (address);
    }

    // Represents the diamond proxy of the ZK chain on L1
    #[sol(rpc)]
    contract ZkChain {
        function owner() external view returns (address);

        // Getters facet
        function getAdmin() external view returns (address);
        function facets() external view returns (Facet[] memory);
        function getVerifier() external view returns (address);
        function getTransactionFilterer() external view returns (address);

        // Admin facet
        function upgradeChainFromVersion(
            address, // _chainAddress (unused in this specific implementation)
            uint256 _oldProtocolVersion,
            DiamondCutData calldata _diamondCut
        ) external;
        function getTotalBatchesCommitted() external view returns (uint256);
        function getTotalBatchesVerified() external view returns (uint256);
        function getTotalBatchesExecuted() external view returns (uint256);
    }

    #[sol(rpc)]
    contract ZkChainV30 {
        // Admin facet
        function upgradeChainFromVersion(uint256 _protocolVersion, DiamondCutData calldata _cutData) external;
    }

    #[sol(rpc)]
    contract ChainAdmin {
        function owner() external view returns (address);
        function multicall(Call[] calldata _calls, bool _requireSuccess) external payable;
    }

    #[sol(rpc)]
    contract ServerNotifier {
        function setUpgradeTimestamp(uint256 _chainId, uint256 _upgradeTimestamp) external;
    }

    #[sol(rpc)]
    contract ServerNotifierV30 {
        // v30.2 variant: _protocolVersion is the old (current) version being upgraded from.
        function setUpgradeTimestamp(uint256 _chainId, uint256 _protocolVersion, uint256 _upgradeTimestamp) external;
    }

    struct L2CanonicalTransaction {
        uint256 txType;
        uint256 from;
        uint256 to;
        uint256 gasLimit;
        uint256 gasPerPubdataByteLimit;
        uint256 maxFeePerGas;
        uint256 maxPriorityFeePerGas;
        uint256 paymaster;
        uint256 nonce;
        uint256 value;
        uint256[4] reserved;
        bytes data;
        bytes signature;
        uint256[] factoryDeps;
        bytes paymasterInput;
        bytes reservedDynamic;
    }

    struct VerifierParams {
        bytes32 recursionNodeLevelVkHash;
        bytes32 recursionLeafLevelVkHash;
        bytes32 recursionCircuitsSetVksHash;
    }

    struct ProposedUpgrade {
        L2CanonicalTransaction l2ProtocolUpgradeTx;
        bytes32 bootloaderHash;
        bytes32 defaultAccountHash;
        bytes32 evmEmulatorHash;
        address verifier;
        VerifierParams verifierParams;
        bytes l1ContractsUpgradeCalldata;
        bytes postUpgradeCalldata;
        uint256 upgradeTimestamp;
        uint256 newProtocolVersion;
    }

    // Bytecode for default upgrade is hardcoded, since putting it to dependencies would significantly
    // slow down the compilation process of integration tests.
    // If you need to change it, take the `bytecode` from `contracts/l1-contracts/out/DefaultUpgrade.sol/DefaultUpgrade.json`
    #[sol(
        rpc,
        bytecode = ""
    )]
    contract DefaultUpgrade {
        function upgrade(ProposedUpgrade calldata _proposedUpgrade) public virtual returns (bytes32 txHash);
    }

    enum ContractUpgradeType {
        EraForceDeployment,
        ZKsyncOSSystemProxyUpgrade,
        ZKsyncOSUnsafeForceDeployment
    }

    struct UniversalContractUpgradeInfo {
        ContractUpgradeType upgradeType;
        bytes deployedBytecodeInfo;
        address newAddress;
    }

    #[sol(rpc)]
    contract L2ComplexUpgrader {
        function forceDeployAndUpgradeUniversal(
            UniversalContractUpgradeInfo[] calldata _forceDeployments,
            address _delegateTo,
            bytes calldata _calldata
        ) external payable;
    }

    /// Struct used to pass bytecode info for force deployment of ZKsyncOS contracts.
    struct ForceDeploymentBytecodeInfo {
        bytes32 bytecodeHash;
        uint32 bytecodeSize;
        bytes32 observableBytecodeHash;
    }

    #[sol(rpc)]
    contract BytecodesSupplier {
        /// @notice Publishes multiple EVM bytecodes.
        function publishEVMBytecodes(bytes[] calldata _bytecodes) external;
    }

    // Executor + Committer facets carrying era-contracts#2323 (chain config hash in the batch
    // proof public input, chain-id-less batchOutputHash). A v31 -> v32 upgrade must install
    // these: from protocol v32 the server emits the v32 batch format, and only these facets
    // compute the matching hashes on-chain.
    // Hardcoded for the same reason as `CommitterFacetV31` below.
    // Regenerate from `contracts/l1-contracts/out/Executor.sol/ExecutorFacet.json`.
    #[sol(rpc, bytecode = "")]
    contract ExecutorFacetV32 {
        constructor(uint256 _l1ChainId);
    }

    // Regenerate from `contracts/l1-contracts/out/Committer.sol/CommitterFacet.json`.
    #[sol(rpc, bytecode = "")]
    contract CommitterFacetV32 {
        constructor(uint256 _l1ChainId);
    }

    // Bytecode for committer facet is hardcoded, since putting it to dependencies would significantly
    // slow down the compilation process of integration tests.
    // If you need to change it, take the `bytecode` from `contracts/l1-contracts/out/Commiter.sol/CommitterFacet.json`
    #[sol(
        rpc,
        bytecode = ""
    )]
    contract CommitterFacetV31 {
        constructor(uint256 _l1ChainId);

        function commitBatchesSharedBridge(
            address, // _chainAddress
            uint256 _processFrom,
            uint256 _processTo,
            bytes calldata _commitData
        ) external;
    }

}

/// Deployed bytecode of era-contracts#2381's `ZKsyncOSTestnetVerifier` (the testnet dual
/// verifier: routes real proofs by version and accepts magic-13 mock proofs). Installed with
/// `anvil_setCode` over the chain's existing verifier during a v31 -> v32 upgrade, keeping
/// its storage (registered verifier mappings) - the same way `local-chains/v32.0/regenerate.sh`
/// installs the dual verifier. Required from v32 on: the #2323 Executor hands the verifier
/// untruncated per-batch public inputs, which the old verifier misinterprets.
/// Regenerate from `contracts/l1-contracts/out/ZKsyncOSTestnetVerifier.sol/ZKsyncOSTestnetVerifier.json`
/// (`deployedBytecode.object`).
pub const ZKSYNC_OS_TESTNET_VERIFIER_DEPLOYED_BYTECODE: &str = "";
